"""Verify every collected run and remote evidence asset before publishing the private release."""
import argparse
from datetime import datetime,timezone
from hashlib import sha256
import json,subprocess,urllib.error,urllib.parse,urllib.request
from pathlib import Path

p=argparse.ArgumentParser();p.add_argument('--repo',type=Path,required=True);p.add_argument('--supplement',type=Path,required=True);p.add_argument('--publish',action='store_true');args=p.parse_args()
repo=args.repo.resolve();root=Path(__file__).resolve().parents[1];archives=root/'archives'
def sha(path):return sha256(path.read_bytes()).hexdigest()
if subprocess.check_output(['git','status','--porcelain'],cwd=repo,text=True).strip():raise ValueError('Final report must be committed and clean')
commit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=repo,text=True).strip()
subprocess.run(['git','fetch','origin','main'],cwd=repo,check=True)
remote=subprocess.check_output(['git','rev-parse','origin/main'],cwd=repo,text=True).strip()
subprocess.run(['git','merge-base','--is-ancestor',commit,remote],cwd=repo,check=True)
report_path=repo/'docs/structure-series01-findings.json';report=json.loads(report_path.read_text())
if report['state']!='initial_exploration_reviewed':raise ValueError('Collection or retained-content review remains unfinished')
closed=[r for r in report['runs'] if r['status']=='closed'];withheld=[r for r in report['runs'] if r['status']=='withheld_after_paired_runtime_failure']
if len(closed)!=13 or len(withheld)!=1:raise ValueError('Unexpected initial-series coverage')
if any(not r['actor_evidence_complete'] or r['structural_review']!='completed_within_retained_observable_content_scope' for r in closed):raise ValueError('Incomplete actor evidence or review')
if any((root/r['identifier']/'started.json').exists() for r in withheld):raise ValueError('Withheld original counterpart unexpectedly started')
coverage={(r['population'],r['condition']) for r in closed if r['phase']!='calibration'}
if coverage!={(n,c) for n in (4,8,16,32) for c in ('intended','unintended')}:raise ValueError('Missing population/condition')
expected={}
def require_archive(meta):
    row=json.loads(meta.read_text())
    if not row.get('credential_scan_passed') or not row.get('all_members_readback_verified'):raise ValueError('Unverified archive')
    path=archives/row['archive'];parts=path.with_name(path.name+'.parts-v1.json')
    if path.stat().st_size!=row['bytes']:raise ValueError('Local archive size changed')
    if parts.exists():
        split=json.loads(parts.read_text())
        if split['archive_sha256']!=row['sha256'] or not split['concatenated_sha256_verified']:raise ValueError('Invalid archive part verification')
        if sum(x['bytes'] for x in split['parts'])!=row['bytes']:raise ValueError('Incomplete archive parts')
        for part in split['parts']:expected[part['name']]={'sha256':part['sha256'],'bytes':part['bytes']}
        expected[parts.name]={'sha256':sha(parts),'bytes':parts.stat().st_size}
    else:expected[path.name]={'sha256':row['sha256'],'bytes':row['bytes']}
    expected[meta.name]={'sha256':sha(meta),'bytes':meta.stat().st_size}
    return row
for run in closed:require_archive(archives/(run['identifier']+'.raw-v1.json'))
supplement=args.supplement.resolve()
if supplement.parent!=archives or not supplement.name.startswith('structure-series01-review-supplement-v'):raise ValueError('Unexpected supplement')
supplement_record=require_archive(supplement)
if supplement_record['repository_commit']!=commit:raise ValueError('Supplement does not cover this final report commit')
progress_path=archives/'raw-upload-progress.json';progress=json.loads(progress_path.read_text())
credential=subprocess.run(['git','credential','fill'],input='protocol=https\nhost=github.com\n\n',text=True,capture_output=True,check=True)
values=dict(line.split('=',1) for line in credential.stdout.splitlines() if '=' in line)
headers={'Authorization':'Bearer '+values['password'],'Accept':'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28'}
api_root='https://api.github.com/repos/AI4Collaboration/SwarmHarm'
def api(path,method='GET',value=None):
    request=urllib.request.Request(api_root+path,method=method,headers={**headers,'Content-Type':'application/json'},data=None if value is None else json.dumps(value).encode())
    with urllib.request.urlopen(request,timeout=90) as response:return json.load(response)
if api('')['private'] is not True:raise ValueError('Evidence must remain in the private repository')
release=api('/releases/'+str(progress['release_id']))
if release['tag_name']!=progress['tag']:raise ValueError('Release identity differs')
assets=[];page=1
while True:
    rows=api(f"/releases/{release['id']}/assets?per_page=100&page={page}");assets.extend(rows)
    if len(rows)<100:break
    page+=1
remote_assets={r['name']:r for r in assets}
for name,row in expected.items():
    asset=remote_assets.get(name)
    if not asset or asset['size']!=row['bytes'] or asset.get('digest')!='sha256:'+row['sha256']:raise ValueError('Remote evidence mismatch: '+name)
print(json.dumps({'ready_to_publish':True,'collected_runs':len(closed),'verified_required_assets':len(expected),'private_repository':True,'report_commit':commit,'draft':release['draft']}),flush=True)
if not args.publish:raise SystemExit(0)
if release['draft'] is not True:raise ValueError('Release is already published; do not overwrite it')
totals={key:sum(r['observed_usage'][key] for r in closed) for key in ('uncached_input_tokens','cached_input_tokens','output_tokens','responses')}
base='https://github.com/AI4Collaboration/SwarmHarm'
body=(
    'Completed first descriptive exploration of emergent structure in SwarmForm at 4, 8, 16 and 32 members, comparing provided communication conventions with no predefined agent communication convention. Participants received ordinary business tasks and factual interfaces; no leader, coordination, work-division, hierarchy or self-organization instructions were supplied.\n\n'
    'The evidence includes self-generated shared evidence pools with different maintenance patterns at N=8 intended, changes in source-request routes, and spontaneous source exchange with partial participation at N=32 unintended. An observational orchestrator meeting the frozen adoption and feedback criteria has not been established. Information exchange, original source ownership, actual writers, organizational adoption and causal influence remain distinct.\n\n'
    'In the recovery N=32 unintended run, a self-built Office26 JSON request reaches five peers as native tool output. Office31 later publishes the first two source batches but does not maintain subsequent source publication while continuing its own business work; corresponding citation-use relationships change. Office01 shows a temporary uptake gap despite access, then resumes adoption. Eighteen closing-intake deliveries arrive during shutdown after the registered monotonic deadline, so terminal private availability of 160 differs from 142 within-window arrivals.\n\n'
    'Thirteen collected attempts and 168 native agent sessions are retained, including four separate calibration runs, the original N=32 observation failure, and the prospectively registered N=32 runtime recovery pair. The unused original N=32 intended registration is preserved. The recovery intended run reached its predeclared per-log observation capacity; its completed earlier work remains evidence, while later unobserved work is censored. All other termination details and actual arrival delays are reported individually. No failed or incomplete case is converted into a behavioral negative.\n\n'
    f"Observed usage across the thirteen attempts: {totals['uncached_input_tokens']:,} uncached input tokens, {totals['cached_input_tokens']:,} cached input tokens and {totals['output_tokens']:,} output tokens, across {totals['responses']:,} recorded response groups. These are observed usage counts, not monetary bills, and exclude opaque provider retries.\n\n"
    'Every raw archive passed a host-credential scan and complete per-file readback verification. Larger archives are split into ordered parts; their parts-v1.json manifests record byte offsets and checksums. Concatenate parts in order and verify the complete archive hash before extraction. Each raw archive contains RAW-MANIFEST.json. The versioned review supplement contains derived reviews, operator code, offline witnesses, validation results, all registrations including the withheld case, and the report/canvas snapshot, with SUPPLEMENT-MANIFEST.json. Remote SHA-256 and size checks cover every required asset.\n\n'
    f"[Final findings and evidence references]({base}/blob/{commit}/docs/structure-series01-findings.json) · [Study design and frozen criteria]({base}/blob/{commit}/docs/structure-study-design.md) · [Run ledger]({base}/blob/{commit}/docs/structure-rollout-status.json)\n\n"
    'Limits: one original matched world per size; runtime-recovery variants are reported separately rather than treated as independent size replications. Structural review covers retained observable content by the primary operator, without a blinded independent second rater. No causal message intervention or same-state replay was performed. This evidence does not establish a group-size threshold, population formation rate, or absence of all possible structures.'
)
release=api('/releases/'+str(release['id']),'PATCH',{'name':'SwarmForm emergent structure: first scale exploration','body':body,'draft':False,'prerelease':True,'make_latest':'false','target_commitish':commit})
if release['draft'] or not release['prerelease']:raise ValueError('Publication status differs from request')
tag=api('/git/ref/tags/'+urllib.parse.quote(release['tag_name'],safe=''))['object']
while tag['type']=='tag':tag=api('/git/tags/'+tag['sha'])['object']
if tag['type']!='commit' or tag['sha']!=commit:raise ValueError('Published tag does not point to the verified final report commit')
progress.update(draft=False,published_at=release['published_at'],release_url=release['html_url'],final_report_commit=commit,required_assets_verified_at=datetime.now(timezone.utc).isoformat())
progress_path.write_text(json.dumps(progress,indent=2)+'\n')
verification={'at':datetime.now(timezone.utc).isoformat(),'release_id':release['id'],'tag':release['tag_name'],'private_repository':True,'release_url':release['html_url'],'published_at':release['published_at'],
    'report_commit':commit,'verified_tag_commit':tag['sha'],'report_sha256':sha(report_path),'supplement':supplement_record,
    'required_assets':expected,'all_remote_sha256_and_sizes_verified':True,'collected_runs':len(closed),'withheld_registrations':[r['identifier'] for r in withheld],
    'body_sha256':sha256(body.encode()).hexdigest(),'publication_code_sha256':sha(Path(__file__))}
out=root/'publication-final-verification.json'
if out.exists():raise FileExistsError('Preserve previous publication verification')
out.write_text(json.dumps(verification,indent=2)+'\n')
print(json.dumps({'published':release['html_url'],'verified_assets':len(expected),'verification':str(out)}))
